import random, copy, numpy as np, scipy.sparse as sp, scipy.sparse.linalg as spla
from reference import Task

def fast_solve(problem):
    A=problem['matrix']; k=problem['k']; n=A.shape[0]
    v0=np.ones(n, dtype=A.dtype)
    k2=min(k+3, n-2)
    try:
        w, v = spla.eigs(A, k=k2, v0=v0, ncv=20, maxiter=n*50)
    except spla.ArpackNoConvergence:
        w, v = spla.eigs(A, k=k2, v0=v0, ncv=20, maxiter=n*200)
    # pick top k by modulus
    idx=np.argsort(-np.abs(w))[:k]
    vectors=v[:, idx].T
    return list(vectors)

task=Task()
random.seed(0); seeds=random.sample(range(1000000),300)
for seed in seeds:
    p=task.generate_problem(n=300, random_seed=seed)
    sol=fast_solve(copy.deepcopy(p))
    if not task.is_solution(p, sol):
        print('fail at',seed)
        break
else:
    print('all pass 300')
