import random, copy, numpy as np, scipy.sparse.linalg as spla
from reference import Task

def fast_solve(problem):
    A=problem['matrix']; k=problem['k']; n=A.shape[0];
    v0=np.ones(n, dtype=A.dtype)
    # Use lower iteration limit for speed, but keep same ncv; relax tol
    try:
        w,v = spla.eigs(A, k=k, v0=v0, ncv=max(2*k+1,20), maxiter=n*20, tol=1e-4)
    except spla.ArpackNoConvergence as e:
        # Get converged eigenvectors if sufficient
        if e.eigenvectors is not None and e.eigenvectors.shape[1] == k:
            w,evecs = e.eigenvalues, e.eigenvectors
            v=evecs
        else:
            # fall back to reference robust parameters
            w,v = spla.eigs(A, k=k, v0=v0, ncv=max(2*k+1,20), maxiter=n*200, tol=0)
    pairs=list(zip(w, v.T))
    pairs.sort(key=lambda pair: -abs(pair[0]))
    return [vec for _,vec in pairs]

task=Task()
random.seed(0)
seeds=random.sample(range(1000000),500)
for seed in seeds:
    p=task.generate_problem(n=300, random_seed=seed)
    sol=fast_solve(copy.deepcopy(p))
    if not task.is_solution(p, sol):
        print('fail',seed)
        break
else:
    print('all pass 500')
